update public.lessons
set content='{"intro": "Esta aula transforma «Pré-certificado energético» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "O formando deve reconhecer quando o SCE é aplicável, distinguir certificado de pré-certificado, localizar classe energética, validade e identificação do imóvel, e perceber o impacto na publicidade e na transação."}, {"title": "Como aplicar na prática", "body": "Confirmar que o documento corresponde ao imóvel/fração, verificar validade e classe, conferir se houve alterações relevantes e usar a classe correta na publicidade quando exigida."}, {"title": "O que confirmar antes de concluir", "body": "Não reutilize certificado de outra fração nem trate um documento expirado como atual. Existem exclusões e regras específicas que devem ser confirmadas no SCE."}, {"title": "Exemplo profissional", "body": "Exemplo: anúncio de fração T2 usa o certificado do prédio inteiro. O documento deve ser conferido antes da publicação."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Pré-certificado energético» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: anúncio de fração T2 usa o certificado do prédio inteiro. O documento deve ser conferido antes da publicação."}'::jsonb,
    source_url='https://www.sce.pt/',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=145;
