update public.lessons
set content='{"intro": "Esta aula transforma «Moradia com anexo» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "Logradouro, anexos e limites devem ser tratados separando realidade física, descrição registral, matriz e situação urbanística. Muros e utilizações históricas não substituem a delimitação jurídica/técnica."}, {"title": "Como aplicar na prática", "body": "Comparar áreas de terreno, implantação e composição; verificar confrontações e plantas disponíveis; identificar anexos e data/origem; confirmar acessos e eventuais servidões; quando os limites forem determinantes, recomendar levantamento topográfico/cadastral adequado."}, {"title": "O que confirmar antes de concluir", "body": "Nunca apresente um limite desenhado numa fotografia ou portal cartográfico como limite juridicamente certo sem suporte suficiente."}, {"title": "Exemplo profissional", "body": "Exemplo: o proprietário usa uma faixa lateral há décadas, mas a descrição e planta não permitem confirmar que integra o prédio. O anúncio não deve incorporá-la como área própria sem esclarecimento."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve distinguir factos documentados, informação do cliente, estimativas comerciais e matérias que exigem validação especializada. Quando uma conclusão ultrapassa a sua competência, deve identificá-la como pendente e encaminhá-la."}], "takeaway": "Competência concluída: saber tratar «Moradia com anexo» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: o proprietário usa uma faixa lateral há décadas, mas a descrição e planta não permitem confirmar que integra o prédio. O anúncio não deve incorporá-la como área própria sem esclarecimento."}'::jsonb,
    source_url='https://justica.gov.pt/Servicos/Balcao-Casa-Pronta',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=156;
update public.lessons
set content='{"intro": "Esta aula transforma «Terreno ''para 6 moradias''» numa competência de trabalho. No final, deverá conseguir reconhecer a situação, localizar a informação relevante, fazer as verificações essenciais, explicar o resultado ao cliente com rigor e identificar quando é necessária validação especializada.", "sections": [{"title": "O que deve dominar", "body": "RAN e REN são regimes de condicionamento territorial distintos. O formando deve saber identificar a incidência cartográfica e depois consultar o regime aplicável à ação pretendida, evitando respostas absolutas."}, {"title": "Como aplicar na prática", "body": "Confirmar delimitação oficial; identificar a ação concreta; verificar exceções/compatibilidades/procedimentos; registar a data da consulta e a entidade competente quando necessário."}, {"title": "O que confirmar antes de concluir", "body": "Dizer simplesmente ''está em RAN/REN, não constrói'' ou ''há casas ao lado, logo constrói'' é tecnicamente insuficiente."}, {"title": "Exemplo profissional", "body": "Exemplo: a mesma condicionante pode ter efeitos diferentes consoante o uso, a operação e o enquadramento específico."}, {"title": "Erros que deve evitar", "body": "• Repetir informação do proprietário como se estivesse verificada.\n• Usar um documento para provar matéria que pertence a outra fonte.\n• Ignorar a data, validade ou versão consultada.\n• Transformar uma estimativa ou possibilidade em certeza comercial.\n• Omitir uma divergência material por receio de dificultar o negócio."}, {"title": "Limite profissional", "body": "O consultor deve saber localizar informação, detetar riscos e formular perguntas. A interpretação técnica de projeto, a confirmação de edificabilidade e a definição do procedimento urbanístico devem ser validadas por arquiteto, engenheiro, município ou outro técnico competente quando o caso o exija."}], "takeaway": "Competência concluída: saber tratar «Terreno ''para 6 moradias''» com fonte, método, limites profissionais e comunicação transparente.", "case_title": "Aplicação prática", "case_body": "Exemplo: a mesma condicionante pode ter efeitos diferentes consoante o uso, a operação e o enquadramento específico."}'::jsonb,
    source_url='https://diariodarepublica.pt/dr/legislacao-consolidada/decreto-lei/1999-34567875-45232375',
    verified_at=date '2026-08-20',
    legal_sensitive=true
where id=157;
commit;

select c.title as formacao,
       count(*) as aulas,
       count(*) filter(where l.verified_at=date '2026-08-20') as verificadas_20082026
from public.courses c
join public.modules m on m.course_id=c.id
join public.lessons l on l.module_id=m.id
where c.slug='documentacao-imobiliaria-profissional'
group by c.id,c.title;
